  gap: 8px;
}

.ztd-actions {
  flex-shrink: 0;
}

.ztd-control {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 44px;
  min-height: 44px;
  padding: 8px 12px;
  border: 1px solid var(--ztd-border);
  border-radius: 8px;
  background: var(--ztd-surface);
  color: var(--ztd-foreground);
  font: inherit;
  white-space: nowrap;
  cursor: pointer;
}

.ztd-control:hover,
.ztd-control[data-state="open"] {
  background: var(--ztd-muted);
}

.ztd-appbar .ztd-control {
  position: relative;
  isolation: isolate;
  gap: 6px;
  padding-inline: 8px;
  border-color: transparent;
  background: transparent;
  font-size: 13px;
  line-height: 18px;
}

.ztd-appbar .ztd-control::before {
  position: absolute;
  z-index: -1;
  inset: 6px 0;
  border-radius: 6px;
  content: "";
}

.ztd-appbar .ztd-control:hover,
.ztd-appbar .ztd-control[data-state="open"] {
  background: transparent;
}

.ztd-appbar .ztd-control:hover::before,
.ztd-appbar .ztd-control[data-state="open"]::before {
  background: var(--ztd-muted);
}

.ztd-frontend :focus-visible,
