  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 8px 8px 8px 28px;
  border-radius: 8px;
  cursor: default;
  user-select: none;
}

.ztd-menu-item[data-highlighted] {
  outline: 2px solid var(--ztd-focus);
  outline-offset: -2px;
  background: var(--ztd-muted);
}

.ztd-indicator {
  position: absolute;
  inset-inline-start: 8px;
  display: flex;
}

.ztd-separator {
  height: 1px;
  margin: 6px;
  background: var(--ztd-border);
}

.ztd-swatch {
