}

.ztd-footer a {
  color: var(--ztd-foreground);
  text-underline-offset: 3px;
}

.ztd-skip {
  position: fixed;
  inset-block-start: 8px;
  inset-inline-start: 8px;
  z-index: 200;
  padding: 12px;
  background: var(--ztd-surface);
  color: var(--ztd-foreground);
  transform: translateY(-200%);
}

.ztd-skip:focus {
  transform: none;
}

