  display: flex;
}

.ztd-workspace > main {
  flex: 1;
  min-width: 0;
}

@media (width < 1024px) {
  .ztd-chrome {
    padding-inline: max(24px, env(safe-area-inset-left));
  }

  .ztd-appbar .ztd-chrome {
    min-height: 64px;
  }
}

@media (width < 640px) {
  .ztd-chrome {
    padding-inline: max(16px, env(safe-area-inset-left));
  }

  .ztd-wide-label {
    display: none;
  }

  .ztd-footer .ztd-chrome {
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 12px;
  }

  .ztd-footer-links {
    flex-wrap: wrap;
    gap: 12px;
  }
}

.ztd-menu {
  --ztd-menu-x: 0px;
  --ztd-menu-y: 0px;

  box-shadow: 0 4px 16px color-mix(in srgb, var(--ztd-foreground) 10%, transparent);
  transform-origin: var(--radix-dropdown-menu-content-transform-origin,
    var(--radix-select-content-transform-origin, center));
}

.ztd-menu[data-side="bottom"] {
  --ztd-menu-y: -4px;
}

.ztd-menu[data-side="top"] {
  --ztd-menu-y: 4px;
}

.ztd-menu[data-side="left"] {
  --ztd-menu-x: 4px;
}

.ztd-menu[data-side="right"] {
  --ztd-menu-x: -4px;
}

.ztd-menu[data-state="open"] {
  animation: ztd-menu-enter 150ms ease-out;
}

.ztd-menu[data-state="closed"] {
  pointer-events: none;
  animation: ztd-menu-exit 100ms ease-in;
}

@keyframes ztd-menu-enter {
  from {
    opacity: 0;
    transform: translate(var(--ztd-menu-x), var(--ztd-menu-y)) scale(0.95);
  }

  to {
    opacity: 1;
    transform: translate(0, 0) scale(1);
  }
}

@keyframes ztd-menu-exit {
  from {
    opacity: 1;
    transform: translate(0, 0) scale(1);
  }

  to {
    opacity: 0;
    transform: translate(var(--ztd-menu-x), var(--ztd-menu-y)) scale(0.95);
  }
}

@media (pointer: coarse) {
  .ztd-menu-item {
    min-height: 44px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ztd-menu[data-state] {
    animation: none;
  }
}

